<section class="page-head"><div><p class="eyebrow">SOURCE</p><h1>Source sections</h1><p class="lead compact"><?=count($sections)?> spine items in EPUB reading order. Keep and Review are initial recommendations.</p></div><a class="button" href="<?=e(rtrim((string)config('app.base_path',''),'/'))?>/logical_sections.php?project=<?=e(rawurlencode($project['id']))?>">Build audiobook structure</a></section>
